{-# LANGUAGE OverloadedStrings #-}
-- | Negative tenant-isolation checks against independently signed HS256 JWTs.
-- Tokens are generated by scripts/generate-jwt-fixtures.py and are NOT stubs.
module TenantIsolationSpec (spec) where

