tenantToken   = "eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJzdWIiOiI0MiIsIm5hbWUiOiJ0ZXN0LXVzZXIiLCJyb2xlIjoidXNlciIsImF1ZCI6InN1cnlwdXMtYXBpIiwiaWF0IjoxNzM1Njg5NjAwLCJleHAiOjQxMDI0NDQ4MDAsInRlbmFudF9pZCI6N30.fybEupOEJKwEgCX2cQ6DCNnL4gjS2HwX5CMEc37KVcM"
noTenantToken = "eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJzdWIiOiI0MiIsIm5hbWUiOiJ0ZXN0LXVzZXIiLCJyb2xlIjoidXNlciIsImF1ZCI6InN1cnlwdXMtYXBpIiwiaWF0IjoxNzM1Njg5NjAwLCJleHAiOjQxMDI0NDQ4MDB9.GlhDduTUkWPSKhZ9NxWS2gpRo17CtUvYmbrUO4fJlPw"
expiredToken  = "eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJzdWIiOiI0MiIsIm5hbWUiOiJ0ZXN0LXVzZXIiLCJyb2xlIjoidXNlciIsImF1ZCI6InN1cnlwdXMtYXBpIiwiaWF0IjoxNjAwMDAwMDAwLCJleHAiOjE2MDAwMDM2MDAsInRlbmFudF9pZCI6N30.j6cX7OozgB0YafjZV7AkghAsUeG0-5Hf8wLfWH2mt_M"
wrongAudToken = "eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJzdWIiOiI0MiIsIm5hbWUiOiJ0ZXN0LXVzZXIiLCJyb2xlIjoidXNlciIsImF1ZCI6Im90aGVyLWFwaSIsImlhdCI6MTczNTY4OTYwMCwiZXhwIjo0MTAyNDQ0ODAwLCJ0ZW5hbnRfaWQiOjd9.CNBZMz6S5HE4HewPGJLDmNSzxTaGDbaHTD7TZRisw4w"
noSubToken    = "eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJuYW1lIjoidGVzdC11c2VyIiwicm9sZSI6InVzZXIiLCJhdWQiOiJzdXJ5cHVzLWFwaSIsImlhdCI6MTczNTY4OTYwMCwiZXhwIjo0MTAyNDQ0ODAwLCJ0ZW5hbnRfaWQiOjd9.QsRws8BUu8OdIO7P8htqB10SFuMoteEr2tYODMq7hAg"
tamperedToken = "eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJzdWIiOiI0MiIsIm5hbWUiOiJ0ZXN0LXVzZXIiLCJyb2xlIjoidXNlciIsImF1ZCI6InN1cnlwdXMtYXBpIiwiaWF0IjoxNzM1Njg5NjAwLCJleHAiOjQxMDI0NDQ4MDAsInRlbmFudF9pZCI6N30.fybEupOEJKwEgCX2cQ6DCNnL4gjS2HwX5CMEc37Kabc"

withSecret :: IO a -> IO a
withSecret = bracket_ (setEnv "SURYPUS_JWT_SECRET" secret)
                      (unsetEnv "SURYPUS_JWT_SECRET")

spec :: Spec
spec = describe "tenant isolation (verified JWT claim only)" $ do
  it "derives tenant and user ids from a signed tenant_id claim" $ withSecret $ do
    result <- resolveTenantFromJWT (T.pack tenantToken)
    case result of
      Right ctx -> do
        tcTenantId ctx `shouldBe` 7
        tcUserId ctx `shouldBe` 42
        tcSchemaName ctx `shouldBe` "public"
      Left err -> fail ("unexpected rejection: " ++ show err)

  it "rejects a valid token without tenant_id" $ withSecret $ do
    result <- resolveTenantFromJWT (T.pack noTenantToken)
    isLeft result `shouldBe` True

  it "rejects an expired token" $ withSecret $ do
    result <- resolveTenantFromJWT (T.pack expiredToken)
    isLeft result `shouldBe` True

  it "rejects a token with the wrong audience" $ withSecret $ do
    result <- resolveTenantFromJWT (T.pack wrongAudToken)
    isLeft result `shouldBe` True

  it "rejects a token without sub" $ withSecret $ do
    result <- resolveTenantFromJWT (T.pack noSubToken)
    isLeft result `shouldBe` True

  it "rejects a tampered signature" $ withSecret $ do
    result <- resolveTenantFromJWT (T.pack tamperedToken)
    isLeft result `shouldBe` True

  it "rejects a non-JWT string" $ withSecret $ do
    result <- resolveTenantFromJWT "not-a-jwt"
    isLeft result `shouldBe` True
